INSERT INTO requirements (id, semantic_id, category, title, description, status) VALUES ('d9bac94e-5cef-4ec0-afc6-3275e4a0264e', 'RQ-AUTH-001', 'AUTH', '간편 소셜 로그인 연동', '사용자는 네이버, 카카오, 애플 계정을 활용하여 소셜 로그인을 수행한다. 단, 애플 로그인은 정책상 iOS 기기 환경에서만 노출되도록 제어한다. 소셜 계정 인증 성공 시 즉시 휴대폰 본인인증 모듈로 리다이렉트된다.', 'In Progress');
INSERT INTO requirements (id, semantic_id, category, title, description, status) VALUES ('a0dbb22e-0f4d-49df-8806-983d94f4f66b', 'RQ-AUTH-002', 'AUTH', '필수 휴대폰 본인인증 및 약관 동의', '본인인증을 완료하여 개인정보(실명, 생년월일, 성별, 전화번호, CI)를 획득한다. 획득한 CI 기반 대조 결과 완전히 새로운 유저일 경우 필수 서비스 이용약관 동의 절차를 거쳐 최종 가입을 완료한다.', 'In Progress');
INSERT INTO requirements (id, semantic_id, category, title, description, status) VALUES ('2c5bf1e3-6b59-4340-b15f-d826d8bed255', 'RQ-AUTH-003', 'AUTH', 'CI 중복 대조 및 멀티로그인 연동', '본인인증을 통과한 신규 소셜 채널의 CI가 이미 DB에 존재하지만 가입된 소셜 채널이 다를 경우(예: 기존에 카카오로 가입했으나 이번에 네이버로 로그인함), 기존 계정에 해당 소셜 채널을 추가로 연동(멀티로그인)할 것인지 묻는 확인 창을 제공하고 연동 처리를 수행한다.', 'In Progress');
INSERT INTO requirements (id, semantic_id, category, title, description, status) VALUES ('af68c59e-abc2-4614-9de6-6f3dbe4131af', 'RQ-AUTH-004', 'AUTH', '동일 채널 중복 가입 차단 및 로그인 유도', '본인인증 결과 획득한 CI와 동일한 소셜 채널 계정이 이미 존재하는 경우(예: 이미 카카오로 가입해놓고 다시 카카오 가입 시도), 가입을 차단하고 기존 가입된 정보를 모달 팝업으로 안내한 뒤 바로 로그인을 유도한다.', 'In Progress');
INSERT INTO requirements (id, semantic_id, category, title, description, status) VALUES ('9844d763-2f08-403a-9c2d-3cebf5a819ac', 'RQ-MEM-001', 'MEM', '본인인증 정보 수정 제한 및 어드민 예외', '사용자는 닉네임 외의 실명, 생년월일, 전화번호를 마이페이지에서 수정할 수 없다. 단, CS 대응을 위해 어드민(관리자) 페이지에서 인증 정보를 초기화/제거할 수 있는 예외 기능을 제공한다.', 'In Progress');
INSERT INTO requirements (id, semantic_id, category, title, description, status) VALUES ('52d29321-2a77-4f02-8aa0-b625de66fecc', 'RQ-SEC-001', 'SEC', '본인확인 개인정보 암호화 보관', '수집한 CI(단방향 SHA-256), 전화번호 및 생년월일(양방향 AES-256)을 법적 규격에 맞춰 안전하게 암호화 보관한다.', 'In Progress');
INSERT INTO requirements (id, semantic_id, category, title, description, status) VALUES ('90d42b35-1ce4-4704-82bb-0e87d47c22dd', 'RQ-COMM-001', 'COMM', '비회원 제한 및 가입 유도', '로그인하지 않은 사용자는 전체 피드 및 게시글 상세 조회가 가능하나, 글작성/댓글작성/좋아요/북마크 등 인터랙션 버튼을 누르는 순간 소셜 로그인 유도 모달 팝업을 노출한다.', 'In Progress');
INSERT INTO requirements (id, semantic_id, category, title, description, status) VALUES ('179276cc-bf47-4bc0-a21e-762d5a0dcad8', 'RQ-COMM-002', 'COMM', '메인 피드 화면 구성 및 리스트 노출', '전체 게시글 리스트를 카드 형태로 노출한다. 좋아요 수치는 채워진 하트/비어있는 하트로 상태를 구분하며 비회원은 비어있는 하트로 노출한다. 우측 상단에는 알림 뱃지와 햄버거(☰) 메뉴를 노출하며, 우측 하단에는 스크롤 방향에 따라 동적으로 [글쓰기✏️]와 [TOP↑]으로 상호 전환되는 반응형 플로팅 버튼(FAB)을 제공한다. 추가로 iOS에서는 상단 상태바 탭 시 피드 최상단으로 이동한다.', 'In Progress');
INSERT INTO requirements (id, semantic_id, category, title, description, status) VALUES ('3dfac957-fe9c-4669-a672-56c15a73fa4a', 'RQ-COMM-003', 'COMM', '거주지 비공개/미인증 예외 처리', '게시글 카드 작성자의 아파트 거주 정보가 비공개 설정되어 있거나 인증된 아파트가 없는 경우, 아파트명 위치에 사용자의 거주 행정구역(예: ''강남구'')이 대신 노출되도록 예외 처리한다.', 'In Progress');
INSERT INTO requirements (id, semantic_id, category, title, description, status) VALUES ('02ed4fba-89e8-481e-abb0-9b2f7385eb29', 'RQ-COMM-004', 'COMM', '피드 정렬 필터 Chips 및 인기글 가중치', '피드 리스트 상단에 최신글/인기글 토글 필터 칩(라디오 방식 택 1)을 제공한다. 인기글은 나중에도 튜닝 가능하도록 가중치 연산식을 적용하여 정렬한다.', 'In Progress');
INSERT INTO requirements (id, semantic_id, category, title, description, status) VALUES ('37330e81-e71f-469e-b04e-5de225cee31a', 'RQ-COMM-005', 'COMM', '아코디언 지역 필터 드로어 인터랙션', '피드 상단 좌측의 지역 표시(기본 ''모든 지역'')를 터치하면, 좌측에서 70% 너비의 드로어 메뉴가 열린다. 지역 목록은 ''모든 지역, 서울, 신도시 1기, 신도시 2기, 신도시 3기'' 등의 뎁스(Depth) 구조로 노출되며, 아코디언 방식으로 상위 항목 터치 시 하위 항목이 펼쳐지고 기존에 열려있던 항목은 닫힌다(Auto-collapse). 선택 시 피드가 필터링된다.', 'In Progress');
INSERT INTO requirements (id, semantic_id, category, title, description, status) VALUES ('c9e79278-9e66-46c3-aa4a-2d70dc189ec8', 'RQ-ENT-001', 'ENT', '스플래시 화면 및 코드푸시 분기', '앱 실행 시 스플래시 로고를 노출하고 토큰 만료 여부 및 최소 버전을 검증한다. 배포 플래그(isMandatory) 강제(true) 시 하단에 ''최적화 중'' 문구를 띄우고 즉시 코드푸시를 다운로드(IMMEDIATE)하며, 일반 배포 시 백그라운드 다운로드 처리한다. 세션이 없는 사용자는 온보딩 화면으로 진입한다.', 'In Progress');
INSERT INTO requirements (id, semantic_id, category, title, description, status) VALUES ('70597f58-6d8c-49db-847d-f5999aa7bb43', 'RQ-AUTH-005', 'AUTH', '자동 로그인 및 세션 유지', '로그인에 성공한 사용자는 앱을 완전히 종료 후 재실행하더라도 로그인 상태가 지속적으로 유지되어 메인 피드로 즉시 진입한다.', 'In Progress');
INSERT INTO requirements (id, semantic_id, category, title, description, status) VALUES ('2f63cf34-e163-4ee8-a0be-163cac64ab42', 'RQ-ENT-002', 'ENT', '강제 업데이트 제어', '앱 초기화 시 앱 버전 검증 API를 호출하여, 현재 설치된 버전이 최소 지원 버전(Min Version) 미만인 경우 강제 업데이트 대상으로 판단하고 스토어로 이동시키는 화면(UI-007)을 노출해 진입을 차단한다.', 'In Progress');
INSERT INTO requirements (id, semantic_id, category, title, description, status) VALUES ('2ac32b40-7f0f-4953-b879-8d13e6c17570', 'RQ-ENT-003', 'ENT', '최초 실행 기기 권한 안내', '앱 최초 실행(진입) 시에는 푸시 알림 수신 권한만 안내 및 동의를 요청한다. 사진첩 및 위치 정보 권한은 최초 실행 시 획득하지 않고, 실제 사용 시점(사진 첨부 시도, 위치 태그 시도 등)에 개별적으로(Just-In-Time) 요청하도록 처리한다.', 'In Progress');
INSERT INTO requirements (id, semantic_id, category, title, description, status) VALUES ('9ec351bf-a0e5-4728-a5af-305e3a193e3d', 'RQ-AUTH-006', 'AUTH', '자동 로그인 만료 예외 대응', '자동 로그인 토큰의 만료 또는 예외 발생 시, 사용자에게 세션 만료 사실을 팝업으로 알리고 최초 로그인 진입 화면으로 안전하게 되돌려 보낸다.', 'In Progress');
INSERT INTO requirements (id, semantic_id, category, title, description, status) VALUES ('78256982-4e0c-4429-a2bb-4ae2b65313fb', 'RQ-ENT-004', 'ENT', '오프라인 및 네트워크 단절 전역 핸들링', '앱 구동 시 혹은 사용 중 네트워크(Wi-Fi, 셀룰러) 단절이 감지되거나 API 호출 실패 시, 전역 인터셉터에서 이를 감지하여 화면 전체를 딤드(Dimmed) 처리하고 오프라인 경고 및 재시도 유도 팝업(UI-009)을 노출한다.', 'In Progress');
INSERT INTO requirements (id, semantic_id, category, title, description, status) VALUES ('64d5d082-9e49-42b5-a6bb-76cde564f310', 'RQ-ENT-005', 'ENT', '글로벌 바텀 네비게이션 바 및 하이브리드 UX 제어', '하단 고정 바텀탭 5개(홈, 미정, 메뉴, 미정, 마이페이지)를 구성하고 현재 화면 탭 활성화(Active State Color/Bold)를 적용한다. 탭별 로그인 옵션 플래그(requiresAuth: boolean)로 5번 클릭 시 로그인 모달(UI-005)을 노출하고 2/4번 클릭 시 ''TBD'' 토스트를 노출한다. 탭 이동 간 화면 상태 및 스크롤을 유지(Keep-Alive)하며, 활성 탭 재클릭 시 최상단 스크롤 및 피드를 새로고침(Fetch)한다.', 'In Progress');
INSERT INTO requirements (id, semantic_id, category, title, description, status) VALUES ('1878b3a3-ad40-4a13-9dd4-b35106d1af93', 'RQ-COMM-006', 'COMM', '리스트 빈 화면 처리 (Empty State)', '[UI-011] 커뮤니티 목록 호출 시 조회된 게시글 데이터가 없을 경우, \"아직 작성된 글이 없습니다\" 등의 텍스트와 함께 빈 화면 전용 일러스트(또는 아이콘)를 노출한다.', 'In Progress');
INSERT INTO requirements (id, semantic_id, category, title, description, status) VALUES ('c27f559e-3855-46d6-ae4d-9679eaf416df', 'RQ-COMM-007', 'COMM', '당겨서 새로고침 (Pull-to-Refresh)', '커뮤니티 목록 등 스크롤이 발생하는 화면 최상단에서 아래로 스와이프 시 로딩 인디케이터를 노출하며 최신 데이터를 다시 호출한다.', 'In Progress');
INSERT INTO requirements (id, semantic_id, category, title, description, status) VALUES ('fd777e18-856d-49b3-8a91-421ebb0decd7', 'RQ-ENT-006', 'ENT', '알림 아이콘 뱃지 (Notification Badge)', '우측 상단 종 모양(알림) 아이콘에 읽지 않은 신규 알림이 있을 경우, 아이콘 우측 상단에 붉은색 뱃지(Dot 또는 N 숫자)를 표시한다.', 'In Progress');
INSERT INTO requirements (id, semantic_id, category, title, description, status) VALUES ('74d411b8-ef65-451a-b160-71675b8aa357', 'RQ-ENT-007', 'ENT', '전역 에러 핸들링 (API Exception Routing)', '서버 API 응답 코드가 특정 치명적 에러(예: error_code == \"999999\")일 경우, 하위 컴포넌트의 에러 처리를 무시하고 즉시 전역 에러 안내 화면(Fallback UI)으로 강제 라우팅 처리한다.', 'In Progress');
INSERT INTO requirements (id, semantic_id, category, title, description, status) VALUES ('6474c6db-e063-4342-83e0-677ef3cbe222', 'RQ-ENT-008', 'ENT', '전역 에러 핸들링 폴백', '서버 API 호출 중 기타 치명적 시스템 오류가 발생했을 때 글로벌 Fallback UI(UI-012)를 통해 에러를 캐치하고 사용자에게 명확한 출구(홈으로 돌아가기, 다시 시도)를 제공한다.', 'In Progress');
INSERT INTO requirements (id, semantic_id, category, title, description, status) VALUES ('6d38136f-9ac3-48b4-988b-46b1f62878de', 'RQ-ENT-009', 'ENT', '긴급 서버 점검 제어', '앱 초기화 시 시스템 상태 API를 호출하여, 서버가 점검 상태(Maintenance)인 경우 진입을 차단하고 서버로부터 수신한 동적 점검 안내 텍스트와 예상 종료 시각을 포함한 화면(UI-013)을 노출한다.', 'In Progress');
INSERT INTO requirements (id, semantic_id, category, title, description, status) VALUES ('5d557aec-9d1a-4b04-86b4-335ce23236e9', 'RQ-COMM-008', 'COMM', '전체화면 메뉴 사이드 모달', '우측 상단 햄버거 메뉴 터치 시 우측에서 슬라이드 인(Slide-in)되는 불투명 전체화면 모달을 노출한다. 즐겨찾는 메뉴 및 일반 메뉴가 1행 1메뉴 구조로 노출되며, 소메뉴는 들여쓰기로 계층을 구분한다. 우측의 별표(⭐) 터치 시 즐겨찾기 등록/해제 처리된다. 현재 진입해 있는 화면의 메뉴 터치 시 화면 이동 없이 모달만 즉시 닫히며, 메뉴 내 프로필이나 유틸리티 요소는 배제한다.', 'In Progress');
INSERT INTO ui_specs (id, semantic_id, title, description, image_url) VALUES ('ac8bba1d-cb4f-4cf8-9f69-844f9c59d480', 'UI-001', '온보딩 및 로그인 화면 기획', '■ 주요 인터랙션 명세 (UI Spec) [대응: RQ-AUTH-001, RQ-ENT-001, RQ-AUTH-006]\n\n1. 화면 레이아웃 및 텍스트 버튼\n- 상단: 서비스 로고 및 소개 일러스트 노출\n- 중하단: ''둘러보기'' 텍스트에 언더라인(Underline)을 적용하여, 시각적으로 방해되지 않으면서도 클릭 가능(Pressable)함을 은은하게 인지시킴\n- 하단: [카카오], [네이버], [애플] 소셜 로그인 원형 아이콘\n\n2. 인증 직행 라우팅 및 액션\n- 소셜 로그인 버튼 클릭: OAuth2 성공 즉시 ''본인인증 모듈''로 리다이렉트 처리 (인증 완료된 유저는 백엔드 토큰 발급 후 메인으로 자동 진입)\n- ''둘러보기'' 텍스트 클릭: 세션 없이 [비회원 피드 UI-005] 즉시 전환', '/wireframes/ui_001.html');
INSERT INTO ui_requirements_map (ui_id, requirement_id) VALUES ('ac8bba1d-cb4f-4cf8-9f69-844f9c59d480', 'd9bac94e-5cef-4ec0-afc6-3275e4a0264e');
INSERT INTO ui_requirements_map (ui_id, requirement_id) VALUES ('ac8bba1d-cb4f-4cf8-9f69-844f9c59d480', 'c9e79278-9e66-46c3-aa4a-2d70dc189ec8');
INSERT INTO ui_requirements_map (ui_id, requirement_id) VALUES ('ac8bba1d-cb4f-4cf8-9f69-844f9c59d480', '9ec351bf-a0e5-4728-a5af-305e3a193e3d');
INSERT INTO ui_specs (id, semantic_id, title, description, image_url) VALUES ('6bdff3d4-dd1d-400a-b5ad-827baf361d36', 'UI-002', '서비스 이용약관 및 가입 완료 기획', '■ 주요 인터랙션 명세 (UI Spec) [대응: RQ-AUTH-002]\n\n1. 요소별 상태(State) 및 액션(Action) 세부 명세\n- [전체 동의] 체크박스: 터치 시 하위 모든 필수/선택 항목 일괄 true 처리. 하위 항목 하나라도 해제 시 전체 동의는 즉시 false로 변경. - 터치 영역(Hitbox) 확장: 체크박스 아이콘뿐만 아니라 약관 텍스트 라벨 영역 전체를 터치 가능 영역으로 설정. - 상세 약관 보기: 각 항목 우측 ''〉'' 아이콘 터치 시, 바텀 시트(Bottom Sheet) 웹뷰 형태로 상세 약관 노출.\n\n2. 유효성 검증 및 버튼 트랜지션\n- 초기 상태: 하단 [가입 완료하기] 버튼 비활성화(Disabled, 회색) - 활성화 조건: 필수 약관 모두 체크되는 순간, 버튼이 활성화(Enabled, 파란색) 색상으로 0.2초 페이드인 트랜지션 됨.', '/wireframes/ui_002.html');
INSERT INTO ui_requirements_map (ui_id, requirement_id) VALUES ('6bdff3d4-dd1d-400a-b5ad-827baf361d36', 'a0dbb22e-0f4d-49df-8806-983d94f4f66b');
INSERT INTO ui_specs (id, semantic_id, title, description, image_url) VALUES ('7895c2a6-8fdd-4924-9ae5-c0e366c12405', 'UI-003', 'CI 대조 분기 및 멀티로그인 기획', '■ 주요 인터랙션 명세 (UI Spec) [대응: RQ-AUTH-003, RQ-AUTH-004]\n\n1. 본인인증 완료 후 백엔드 CI 대조 로직 분기 - 신규 CI: UI-002 약관 동의 화면으로 이동하여 신규 가입 절차 진행. - 기존 가입된 소셜과 동일 채널: 중복 가입 팝업 띄운 후 바로 로그인 처리. - 기존 가입된 소셜과 다른 채널(멀티로그인): 본 화면의 모달 노출.\n\n2. 멀티로그인 제안 모달 액션\n- 딤드(Dimmed) 처리: 모달 외부 영역 터치 시 닫히지 않도록 강제 선택 요구.\n- [기존 계정에 연동]: 클릭 시 로딩 스피너 노출 후 성공 시 피드 UI-011로 이동.\n- [기존 계정으로 로그인]: 클릭 시 현재 로그인 세션 파기 후 UI-001로 복귀.', '/wireframes/ui_003.html');
INSERT INTO ui_requirements_map (ui_id, requirement_id) VALUES ('7895c2a6-8fdd-4924-9ae5-c0e366c12405', '2c5bf1e3-6b59-4340-b15f-d826d8bed255');
INSERT INTO ui_requirements_map (ui_id, requirement_id) VALUES ('7895c2a6-8fdd-4924-9ae5-c0e366c12405', 'af68c59e-abc2-4614-9de6-6f3dbe4131af');
INSERT INTO ui_specs (id, semantic_id, title, description, image_url) VALUES ('e2d580f3-4dc1-4c23-92ab-c7e1c2eb8b12', 'UI-004', '본인인증 정보 수정 제한 및 어드민 예외 기획', '■ 주요 인터랙션 명세 (UI Spec) [대응: RQ-MEM-001]\n\n1. 요소별 상태(State) 및 액션(Action) 명세\n- [닉네임/프로필]: 수정 활성화. 변경 시 특수문자 제한 및 중복 확인 유효성 검증 제공.\n- [실명/생년월일/전화번호]: 수정 불가한 비활성화(Muted Gray) 텍스트로 노출되며 어떠한 입력 폼도 제공하지 않음.\n\n2. 예외처리(Exception) 및 UX\n- [안내 툴팁]: 비활성화 항목 우측의 ''?'' 아이콘 터치 시 \', '/wireframes/ui_004.html');
INSERT INTO ui_requirements_map (ui_id, requirement_id) VALUES ('e2d580f3-4dc1-4c23-92ab-c7e1c2eb8b12', '9844d763-2f08-403a-9c2d-3cebf5a819ac');
INSERT INTO ui_specs (id, semantic_id, title, description, image_url) VALUES ('4c5427ce-c88f-45f3-b15c-034827a93c5c', 'UI-005', '비회원 제한 및 가입 유도 팝업 기획', '■ 주요 인터랙션 명세 (UI Spec) [대응: RQ-COMM-001]\n\n1. 요소별 상태(State) 및 액션(Action) 명세\n- [인터랙션 차단]: 비회원이 ''좋아요'', ''댓글 작성'' 등 터치 시 즉시 중앙 로그인 유도 모달 노출.\n- [백드랍 제어]: 딤드 영역 터치 이벤트를 무시하여 의도치 않은 닫힘 방지. 닫기[X] 버튼으로만 취소 가능.\n\n2. 트랜지션(Transition) 및 예외처리(Exception)\n- [기기별 분기]: 애플 로그인은 앱스토어 심사 정책에 따라 iOS 기기 환경에서만 버튼이 노출되도록 제어함.\n- [이탈 복구]: 인증 도중 취소하더라도 앱 첫 화면으로 튕기지 않고 아까 보던 피드 스크롤 위치와 모달 상태로 원복됨.', '/wireframes/ui_005.html');
INSERT INTO ui_requirements_map (ui_id, requirement_id) VALUES ('4c5427ce-c88f-45f3-b15c-034827a93c5c', '90d42b35-1ce4-4704-82bb-0e87d47c22dd');
INSERT INTO ui_specs (id, semantic_id, title, description, image_url) VALUES ('e401bd3b-4f18-4e3f-b12b-cd21737ad970', 'UI-006', '스플래시 화면 기획', '■ 주요 인터랙션 명세 (UI Spec) [대응: RQ-ENT-001, RQ-AUTH-005]\n\n1. 자동 갱신 및 코드푸시(CodePush) 제어\n- [API 검증]: 백그라운드에서 토큰 만료 여부 및 최소 필수 버전 체크 수행.\n- [코드푸시 분기]: 배포 플래그(isMandatory) 강제(true) 시 ''최적화 중'' 문구 노출 및 즉시 다운로드(IMMEDIATE). 일반(false) 배포 시 스플래시 지연 없이 통과 후 백그라운드 다운로드 처리.\n\n2. 예외처리(Exception) 및 타임아웃\n- [타임아웃 팝업]: 5초 이상 병목 발생 시 무한 로딩 방지 경고 모달 노출.\n- [하드웨어 제어]: 모달 내 [다시 시도]/[앱 종료] 단추 및 물리 뒤로가기 즉시 종료 허용.', '/wireframes/ui_006.html');
INSERT INTO ui_requirements_map (ui_id, requirement_id) VALUES ('e401bd3b-4f18-4e3f-b12b-cd21737ad970', 'c9e79278-9e66-46c3-aa4a-2d70dc189ec8');
INSERT INTO ui_requirements_map (ui_id, requirement_id) VALUES ('e401bd3b-4f18-4e3f-b12b-cd21737ad970', '70597f58-6d8c-49db-847d-f5999aa7bb43');
INSERT INTO ui_specs (id, semantic_id, title, description, image_url) VALUES ('8c374cbe-3468-425f-b05d-e4ffef425a74', 'UI-007', '강제 업데이트 화면 기획', '■ 주요 인터랙션 명세 (UI Spec) [대응: RQ-ENT-002]\n\n1. 요소별 상태(State) 및 액션(Action) 명세\n- [강제 업데이트 화면]: 앱 초기화 API를 통해 수신한 최소 지원 버전 미만일 시 진입. 동적으로 안내 문구를 화면에 바인딩함.\n- [스토어 이동 버튼]: 터치 시 OS(iOS/Android)에 맞는 네이티브 마켓 딥링크 호출.\n\n2. 예외처리(Exception) 및 라이프사이클 제어\n- [화면 이탈 차단]: 뒤로 가기 및 앱 내 타 메뉴 이동 원천 차단.\n- [앱 재개(Resume) 검증]: 유저가 스토어에서 앱을 백그라운드로 내렸다가 포그라운드로 복귀(App Resume)하는 순간 버전을 재검증.', '/wireframes/ui_007.html');
INSERT INTO ui_requirements_map (ui_id, requirement_id) VALUES ('8c374cbe-3468-425f-b05d-e4ffef425a74', '2f63cf34-e163-4ee8-a0be-163cac64ab42');
INSERT INTO ui_specs (id, semantic_id, title, description, image_url) VALUES ('217bc253-e6a3-4a0e-983f-4f971e096d45', 'UI-008', '기기 접근 권한 사전 안내 및 동의 팝업 기획', '■ 주요 인터랙션 명세 (UI Spec) [대응: RQ-ENT-003]\n\n1. 요소별 상태(State) 및 액션(Action) 명세\n- [사전 알림 팝업]: 스플래시 직후 앱 최초 실행 시에만 **[푸시 알림]**에 대한 서비스 안내 모달을 띄운 뒤 OS 권한 승인 창 호출.\n- [JIT(Just-In-Time) 요청]: ''사진첩'', ''위치 정보'' 등의 권한은 초기 진입 시 묻지 않고 실제 기능 탭(예: 글작성 중 이미지 첨부 클릭) 시점에 개별 OS 권한 창 호출.\n\n2. 예외처리(Exception) 및 UX\n- [권한 거절 대응]: 선택 권한 거절 시 기능만 차단. 필수 권한 거절 시 설정 앱으로 이동하라는 안내 얼럿 노출 후 취소 시 앱 종료.', '/wireframes/ui_008.html');
INSERT INTO ui_requirements_map (ui_id, requirement_id) VALUES ('217bc253-e6a3-4a0e-983f-4f971e096d45', '2ac32b40-7f0f-4953-b879-8d13e6c17570');
INSERT INTO ui_specs (id, semantic_id, title, description, image_url) VALUES ('d85952a1-2a13-4639-b572-1db82babb1c4', 'UI-009', '오프라인 네트워크 단절 화면 기획', '■ 주요 인터랙션 명세 (UI Spec) [대응: RQ-ENT-004]\n\n1. 요소별 상태(State) 및 액션(Action) 명세\n- [에러 모달 화면]: 즉각적인 전체 화면 딤드(Dimmed) 처리 후 ''네트워크 미연결'' 팝업 호출. 하단에 [다시 시도], [앱 종료] 버튼 나란히 노출.\n\n2. 트랜지션(Transition) 및 스마트 복구 로직\n- [자동 복구 리스너]: 기기 단에 네트워크 상태 감지 리스너(Listener)를 백그라운드 등록함. Wi-Fi/LTE가 자체 복구되어 정상 감지되는 순간 사용자가 조작하지 않아도 팝업이 즉시 페이드아웃되며 원래 화면으로 복귀함(스마트 UX).', '/wireframes/ui_009.html');
INSERT INTO ui_requirements_map (ui_id, requirement_id) VALUES ('d85952a1-2a13-4639-b572-1db82babb1c4', '78256982-4e0c-4429-a2bb-4ae2b65313fb');
INSERT INTO ui_specs (id, semantic_id, title, description, image_url) VALUES ('3807a722-8a89-4907-befb-8262ea6c1fbb', 'UI-010', '지역 선택 드로어 화면 기획', '■ 주요 인터랙션 명세 (UI Spec) [대응: RQ-COMM-005]\n\n1. 요소별 상태(State) 및 액션(Action) 명세\n- [드로어 레이아웃]: 좌측 70% 너비 슬라이드인(Slide-in) 오픈, 우측 30% 영역 딤드 처리.\n- [스크롤 락(Scroll Lock)]: 드로어가 열려있는 동안 뒷면에 깔린 메인 피드 UI 목록이 상하로 움직이는 불상사를 원천 차단하기 위해 전역 스크롤 락 적용.\n\n2. 트랜지션(Transition) 및 예외처리(Exception)\n- [아코디언 Auto-collapse]: 상위 지역 터치 시 하위 항목 확장. 다른 상위 지역 선택 시 기존 열려있던 항목은 부드럽게 접힘.\n- [피드 연동]: 최종 뎁스의 구/동 선택 즉시 0.3초 애니메이션 닫힘과 동시에 뒷단 메인 피드 리스트 리패치(Refetch).', '/wireframes/ui_010.html');
INSERT INTO ui_requirements_map (ui_id, requirement_id) VALUES ('3807a722-8a89-4907-befb-8262ea6c1fbb', '37330e81-e71f-469e-b04e-5de225cee31a');
INSERT INTO ui_specs (id, semantic_id, title, description, image_url) VALUES ('750c1cca-3263-4668-9f14-483ddb64d1a7', 'UI-011', '메인 피드 화면 기획', '■ 주요 인터랙션 명세 (UI Spec) [대응: RQ-COMM-002, RQ-COMM-003, RQ-COMM-004, RQ-COMM-006, RQ-COMM-007, RQ-ENT-006]\n\n1. 상단 헤더 및 예외처리\n- [헤더 액션]: 붉은 점(Dot) 뱃지가 포함된 알림 아이콘, 그리고 전체화면 모달을 띄우는 메뉴(☰) 아이콘 배치.\n- [당겨서 새로고침]: 스와이프 시 로딩 인디케이터.\n- [빈 화면]: 글이 없을 시 전용 일러스트 노출.\n\n2. 플로팅 액션 버튼(FAB) 및 스크롤(Scroll) 제어\n- [상태바 스크롤]: iOS 상단 상태바(Status Bar) 탭 시 피드 최상단으로 자동 스크롤.\n- [스크롤 반응형 FAB]: 우측 하단 고정. 아래로 스크롤 시 [글쓰기✏️] 숨김 & [TOP↑] 등장. 위로 스크롤 시 다시 [글쓰기✏️] 등장.', '/wireframes/ui_011.html');
INSERT INTO ui_requirements_map (ui_id, requirement_id) VALUES ('750c1cca-3263-4668-9f14-483ddb64d1a7', '179276cc-bf47-4bc0-a21e-762d5a0dcad8');
INSERT INTO ui_requirements_map (ui_id, requirement_id) VALUES ('750c1cca-3263-4668-9f14-483ddb64d1a7', '3dfac957-fe9c-4669-a672-56c15a73fa4a');
INSERT INTO ui_requirements_map (ui_id, requirement_id) VALUES ('750c1cca-3263-4668-9f14-483ddb64d1a7', '02ed4fba-89e8-481e-abb0-9b2f7385eb29');
INSERT INTO ui_requirements_map (ui_id, requirement_id) VALUES ('750c1cca-3263-4668-9f14-483ddb64d1a7', '1878b3a3-ad40-4a13-9dd4-b35106d1af93');
INSERT INTO ui_requirements_map (ui_id, requirement_id) VALUES ('750c1cca-3263-4668-9f14-483ddb64d1a7', 'c27f559e-3855-46d6-ae4d-9679eaf416df');
INSERT INTO ui_requirements_map (ui_id, requirement_id) VALUES ('750c1cca-3263-4668-9f14-483ddb64d1a7', 'fd777e18-856d-49b3-8a91-421ebb0decd7');
INSERT INTO ui_specs (id, semantic_id, title, description, image_url) VALUES ('19bc3d2a-ec13-4133-b34b-0543dfba7d6f', 'UI-012', '글로벌 에러 폴백 화면 기획', '■ 주요 인터랙션 명세 (UI Spec) [대응: RQ-ENT-008]\n\n1. 요소별 상태(State) 및 액션(Action) 명세\n- [전역 에러 라우팅]: 서버 API 호출 중 치명적 오류(error_code: 999999 등) 발생 시, 개별 컴포넌트 처리를 무시하고 화면 전체를 덮는 Fallback 에러 페이지로 즉각 라우팅함.\n- [복귀 제어]: 일러스트 경고문 하단에 [홈으로 돌아가기], [다시 시도] 단일 버튼 제공.\n\n2. 트랜지션(Transition) 및 예외처리(Exception)\n- [연속 실패 방지]: [다시 시도] 버튼 짧은 시간에 다중 연타 시 Debounce 처리 적용. 3회 이상 실패 반복 시 홈 화면으로 강제 튕김 후 재실행 유도 안내.', '/wireframes/ui_012.html');
INSERT INTO ui_requirements_map (ui_id, requirement_id) VALUES ('19bc3d2a-ec13-4133-b34b-0543dfba7d6f', '6474c6db-e063-4342-83e0-677ef3cbe222');
INSERT INTO ui_specs (id, semantic_id, title, description, image_url) VALUES ('b57db9f5-9e87-4441-adf7-c000ab77bfd0', 'UI-013', '긴급 서버 점검 공지 화면 기획', '■ 주요 인터랙션 명세 (UI Spec) [대응: RQ-ENT-009]\n\n1. 요소별 상태(State) 및 액션(Action) 명세\n- [서버 점검 화면]: API 응답이 Maintenance 상태일 시 진입. 점검 사유 및 예상 종료 시각이 API로부터 동적 텍스트로 바인딩되어 노출됨.\n- [앱 종료 버튼]: 팝업 하단의 ''앱 종료'' 터치 시 프로세스 강제 종료 처리.\n\n2. 예외처리(Exception) 및 라이프사이클 제어\n- [화면 이탈 차단]: 뒤로 가기 및 앱 내 타 메뉴 이동 원천 차단.\n- [앱 재개(Resume) 검증]: 백그라운드에서 포그라운드로 복귀 시 점검 상태를 자동 재검증하여 완료되었을 경우 홈 화면으로 자동 라우팅.', '/wireframes/ui_013.html');
INSERT INTO ui_requirements_map (ui_id, requirement_id) VALUES ('b57db9f5-9e87-4441-adf7-c000ab77bfd0', '6d38136f-9ac3-48b4-988b-46b1f62878de');
INSERT INTO ui_specs (id, semantic_id, title, description, image_url) VALUES ('69b570aa-875c-4f4d-91eb-6e7a6f3018a6', 'UI-014', '전체화면 메뉴 (사이드 모달) 기획', '■ 주요 인터랙션 명세 (UI Spec) [대응: RQ-COMM-008]\n\n1. 레이아웃 및 트랜지션 (Transition)\n- [슬라이드 인 모달]: 햄버거 메뉴 터치 시 불투명한 전체화면 패널이 우측에서 좌측으로 부드럽게 진입하며 기존 바텀 네비게이션을 모두 덮음.\n- [헤더]: 중앙에 ''메뉴'' 타이틀, 좌측 상단에 닫기(X) 버튼을 배치하여 명확한 종료 지점 제공.\n\n2. 메뉴 구성 및 즐겨찾기 연동\n- [즐겨찾는 메뉴]: 상단 최상위 영역에 ''⭐ 즐겨찾는 메뉴'' 섹션을 분리 배치하여 사용자 접근성 강화.\n- [들여쓰기 계층]: 대메뉴 하위에 소메뉴를 들여쓰기(Indentation) 방식으로 1행 1메뉴씩 직관적으로 나열함.\n- [별점 토글]: 각 메뉴 우측 끝의 별(⭐) 아이콘 터치 시 활성/비활성 상태가 토글되며 즐겨찾기 섹션에 즉시 연동됨.\n\n3. 예외처리(Exception)\n- [현재 화면 클릭 방지]: 사용자가 현재 진입해 있는 화면의 메뉴 항목을 모달에서 재클릭할 경우, 새로운 라우팅 없이 모달 창만 즉각적으로 페이드아웃(닫힘) 처리됨.', '/wireframes/ui_014.html');
INSERT INTO ui_requirements_map (ui_id, requirement_id) VALUES ('69b570aa-875c-4f4d-91eb-6e7a6f3018a6', '5d557aec-9d1a-4b04-86b4-335ce23236e9');