-- 1. Create Tables

CREATE TABLE IF NOT EXISTS requirements (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    semantic_id VARCHAR(50) UNIQUE NOT NULL,
    category VARCHAR(50),
    title VARCHAR(255) NOT NULL,
    description TEXT,
    status VARCHAR(50) DEFAULT '대기'
);

CREATE TABLE IF NOT EXISTS ui_specs (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    semantic_id VARCHAR(50) UNIQUE NOT NULL,
    title VARCHAR(255) NOT NULL,
    description TEXT,
    image_url VARCHAR(255)
);

CREATE TABLE IF NOT EXISTS ui_requirements_map (
    ui_id UUID REFERENCES ui_specs(id) ON DELETE CASCADE,
    requirement_id UUID REFERENCES requirements(id) ON DELETE CASCADE,
    PRIMARY KEY (ui_id, requirement_id)
);

